//! State-based CRDTs: replicas that converge by merging states, with no coordination.
//!
//! Do not edit this file. Implement the four types in their own modules.

mod gcounter;
mod lww;
mod orset;
mod pncounter;

pub use gcounter::GCounter;
pub use lww::LwwRegister;
pub use orset::OrSet;
pub use pncounter::PnCounter;

/// Identifies one replica. Each live replica must use its own id.
pub type ReplicaId = u32;

/// A state-based CRDT.
///
/// `merge` must be a join: commutative, associative and idempotent. Then any
/// delivery order, duplication or delay of states still converges.
pub trait Crdt: Clone + PartialEq {
    /// Folds `other` into `self`. `other` is never modified.
    fn merge(&mut self, other: &Self);
}

/// Merges every replica's state into every other replica.
///
/// One pass is enough: after replica 0 has merged all others it holds the join
/// of all states, and every later replica merges that join.
pub fn all_pairs_sync<C: Crdt>(replicas: &mut [C]) {
    for i in 0..replicas.len() {
        for j in 0..replicas.len() {
            if i != j {
                let other = replicas[j].clone();
                replicas[i].merge(&other);
            }
        }
    }
}
